class AVLNode:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None
        self.height = 1


def avl_height(node):
    return node.height if node else 0


def balance(node):
    return avl_height(node.left) - avl_height(node.right) if node else 0


def update(node):
    node.height = 1 + max(avl_height(node.left), avl_height(node.right))
    return node


def rotate_right(y):
    x = y.left
    y.left = x.right
    x.right = update(y)
    return update(x)


def rotate_left(x):
    y = x.right
    x.right = y.left
    y.left = update(x)
    return update(y)


def avl_insert(node, data):
    if not node:
        return AVLNode(data)
    if data < node.data:
        node.left = avl_insert(node.left, data)
    else:
        node.right = avl_insert(node.right, data)
    node = update(node)
    b = balance(node)
    if b > 1 and data < node.left.data:
        return rotate_right(node)
    if b < -1 and data > node.right.data:
        return rotate_left(node)
    if b > 1 and data > node.left.data:
        node.left = rotate_left(node.left)
        return rotate_right(node)
    if b < -1 and data < node.right.data:
        node.right = rotate_right(node.right)
        return rotate_left(node)
    return node


def avl_inorder(node, out):
    if node:
        avl_inorder(node.left, out)
        out.append(str(node.data))
        avl_inorder(node.right, out)


